head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldods16510";

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        await scwin.init_rowCopy();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldods16510.onpageload' });
    }
};

/**
 * @method
 * @name init_rowCopy
 * @description dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_rowCopy = async function () {
    const rows = [{ childId: "__rb0", fn: function () { return String((String(String(dma_disclosureSchedule.get("calndDd")) == null ? '' : String(dma_disclosureSchedule.get("calndDd"))) === '' ? '' : String("yyyy-MM-dd").replace(/yyyy/g, String(dma_disclosureSchedule.get("calndDd")).slice(0,4)).replace(/MM/g, String(dma_disclosureSchedule.get("calndDd")).slice(4,6)).replace(/dd/g, String(dma_disclosureSchedule.get("calndDd")).slice(6,8)).replace(/HH/g, String(dma_disclosureSchedule.get("calndDd")).slice(8,10)).replace(/mm/g, String(dma_disclosureSchedule.get("calndDd")).slice(10,12)).replace(/ss/g, String(dma_disclosureSchedule.get("calndDd")).slice(12,14)))); } },
        { childId: "__rb2", fn: function () { return String(String(String(dma_disclosureSchedule.get("schdlContn")) == null ? '' : String(dma_disclosureSchedule.get("schdlContn"))).split(String.fromCharCode(10)).join('<br/>')); } }];
    let copied = 0;
    for (let i = 0; i < rows.length; i++) {
        const it = rows[i];
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { /* TODO Stage2: [sdd] 행 복사 대상 부재:  it.childId */ continue; }
        try {
            const v = it.fn();
            if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); copied++; }
        } catch (e) { await $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); }
    }
    return copied;
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_window_onclick
 * @description 「닫기」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_window_onclick = function(e){
    try {
        $c.win.closePopup()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldods16510.btn_window_onclick' }); }
};

/**
 * @method
 * @name btn_window_2_onclick
 * @description 「레이어닫기」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_window_2_onclick = function(e){
    try {
        $c.win.closePopup()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldods16510.btn_window_2_onclick' }); }
};
